      if (!e.shiftKey && (e.key === 'ArrowRight' || e.key === 'l' || e.key === 'L')) {
        e.preventDefault();
        seekRelative(10);
        return;
      }

      // 4. Next / Previous Episode: Shift + ArrowRight / Shift + ArrowLeft, or 'n' / 'p'
